//! 🧳️ An opaque non-Clone native primary survives the real receiver beside independent qualification refusal.
use super::*;
use semio_framework_job::{OriginalJobFixtureCaller,OperationId,Generation,JobPayloadPageSource,receive_original_retained_work};
use semio_framework_trace::observe_heap_allocations_on_this_thread as observe;
#[global_allocator]
static TRANSPORT_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
struct OpaquePrimary{code:u64,owner:Option<JobPayloadPageSource>}
pub(super) fn bank()->RetainedCloneGrant{let row:serde_json::Value=serde_json::from_str(include_str!("../../../../🛬️receiving/♻️close/📐️.json")).unwrap();let s=&row["stock"];RetainedCloneGrant{maximum_items:s["items"].as_u64().unwrap()as usize,maximum_copy_bytes:s["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:s["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:s["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:s["depth"].as_u64().unwrap()as usize}}
#[test]
fn actual_receiver_preserves_nonclone_native_primary_and_independent_receiving_refusal(){
 let row:serde_json::Value=serde_json::from_str(include_str!("case.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("case.schema.json")).unwrap();for(k,v)in row.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}
 for mismatch in row["receivingMismatch"].as_array().unwrap(){let mismatch=mismatch.as_bool().unwrap();let stock=bank();let grant=RetainedCloneGrant{maximum_items:1,..stock};let mut caller=OriginalJobFixtureCaller::admit(OperationId(7678),Generation(3),stock,||Some(0),1000000,10000);let mut input=None;
  caller.turn(grant,|cx|{let turn=JobPayloadPageSource::admit(1,cx.retained_grant());let result=turn.result.map(|born|{let(owner,p)=born.unwrap();input=Some(OpaquePrimary{code:row["code"].as_u64().unwrap(),owner:Some(owner)});RetainedCloneStep::Progress(p)});receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome{result,work:turn.work})?;Ok(())}).unwrap();let pointer=input.as_ref().unwrap().owner.as_ref().unwrap().backing_identity();let mut output:Option<OriginalNativeDecodeOutcome<(),OpaquePrimary>>=None;
  let(_,heap)=observe(||caller.turn(grant,|cx|{let supplied=cx.retained_grant();assert!(supplied.maximum_items>0&&supplied.maximum_depth>0&&!cx.should_yield());let mut reported=supplied;if mismatch{reported.maximum_depth=0;}let work=cx.original_work_units_spent();output=Some(OriginalNativeDecodeSource::receive_issued(cx,supplied,cx.fuel_remaining(),OriginalNativeDecodeIssued{value:Err(input.take().unwrap()),grant:reported,progress:RetainedCloneProgress{copied_items:row["bodyTransferItems"].as_u64().unwrap()as usize,..Default::default()},work:row["bodyTransferWork"].as_u64().unwrap()}));assert_eq!(cx.original_work_units_spent()-work,u128::from(row["bodyTransferWork"].as_u64().unwrap()));Ok(())}).unwrap());assert!(!heap.overflowed);assert_eq!(serde_json::to_value([heap.requested_bytes,heap.released_bytes]).unwrap(),row["transportHeap"]);assert!(input.is_none());let received=output.as_ref().unwrap();let primary=received.value.as_ref().err().unwrap();assert_eq!(primary.owner.as_ref().unwrap().backing_identity(),pointer);assert_eq!(serde_json::to_value((primary.code,received.receiving_refusal.is_some())).unwrap(),serde_json::json!([row["code"],mismatch]));if let Some(refusal)=received.receiving_refusal.as_ref(){assert_eq!(refusal.primary.message(),"original native producer changed its supplied grant or exceeded its physical receipt");}
  let(_,heap)=observe(||caller.turn(grant,|cx|{let actual=cx.retained_grant();assert!(actual.maximum_items>0&&actual.maximum_depth>0&&actual.maximum_release_bytes>=1&&!cx.retirement_should_yield());drop(output.as_mut().unwrap().value.as_mut().err().unwrap().owner.take());receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome::<_,ValueError>{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:1,..Default::default()})),work:1})?;Ok(())}).unwrap());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,row["releaseBytes"].as_u64().unwrap()as usize));
  caller.turn(grant,|cx|{assert!(cx.retained_grant().maximum_items>0&&cx.retained_grant().maximum_depth>0&&!cx.retirement_should_yield());let(_,heap)=observe(||drop(output.take()));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));receive_original_retained_work(cx,semio_framework_value::RetainedWorkOutcome::<_,ValueError>{result:Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,..Default::default()})),work:1})?;Ok(())}).unwrap();caller.retire(stock);
 }
}
